package ratelimit

import (
	"testing"
	"time"
)

type fakeClock struct {
	t time.Time
}

func (c *fakeClock) Now() time.Time { return c.t }
func (c *fakeClock) Advance(d time.Duration) { c.t = c.t.Add(d) }

func TestNewValidation(t *testing.T) {
	fc := &fakeClock{t: time.Unix(0, 0)}
	tests := []struct {
		name     string
		capacity float64
		rate     float64
		clock    Clock
		wantErr  bool
	}{
		{"valid", 10, 1, fc, false},
		{"zero capacity", 0, 1, fc, true},
		{"negative capacity", -1, 1, fc, true},
		{"zero rate", 10, 0, fc, true},
		{"negative rate", 10, -1, fc, true},
		{"nil clock", 10, 1, nil, true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			_, err := New(tt.capacity, tt.rate, tt.clock)
			if (err != nil) != tt.wantErr {
				t.Fatalf("New(%v,%v) err=%v wantErr=%v", tt.capacity, tt.rate, err, tt.wantErr)
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	tests := []struct {
		name     string
		capacity float64
		rate     float64
		advances []time.Duration
		n        int
		want     []bool
	}{
		{
			name:     "burst then drain",
			capacity: 5,
			rate:     1,
			advances: []time.Duration{0, 0, 0, 0, 0, time.Second},
			n:        1,
			want:     []bool{true, true, true, true, true, true},
		},
		{
			name:     "exceeds capacity",
			capacity: 3,
			rate:     1,
			advances: []time.Duration{0, 0, 0, 0},
			n:        1,
			want:     []bool{true, true, true, false},
		},
		{
			name:     "refill over time",
			capacity: 2,
			rate:     1,
			advances: []time.Duration{0, 0, 2 * time.Second, 0},
			n:        1,
			want:     []bool{true, true, true, true},
		},
		{
			name:     "AllowN multiple",
			capacity: 10,
			rate:     2,
			advances: []time.Duration{0, 0, 3 * time.Second, 0},
			n:        4,
			want:     []bool{true, true, true, false},
		},
		{
			name:     "zero n always allowed",
			capacity: 1,
			rate:     1,
			advances: []time.Duration{0, 0},
			n:        0,
			want:     []bool{true, true},
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			fc := &fakeClock{t: time.Unix(0, 0)}
			l, err := New(tt.capacity, tt.rate, fc)
			if err != nil {
				t.Fatal(err)
			}
			for i, adv := range tt.advances {
				fc.Advance(adv)
				got := l.AllowN(tt.n)
				if got != tt.want[i] {
					t.Errorf("step %d: AllowN(%d)=%v want %v", i, tt.n, got, tt.want[i])
				}
			}
		})
	}
}

func TestConcurrent(t *testing.T) {
	fc := &fakeClock{t: time.Unix(0, 0)}
	l, _ := New(100, 10, fc)
	done := make(chan bool)
	for i := 0; i < 50; i++ {
		go func() { done <- l.Allow() }()
	}
	allowed := 0
	for i := 0; i < 50; i++ {
		if <-done {
			allowed++
		}
	}
	if allowed != 50 {
		t.Errorf("expected 50 allowed, got %d", allowed)
	}
}
